{
  "returncode": 0,
  "output": "   300	  .cards--grid {
   301	    --cards-gap: 1rem;
   302	    --card-grid-columns: 1;
   303	
   304	    container-type: inline-size;
   305	    inline-size: 100%;
   306	    margin-inline: auto;
   307	    max-inline-size: var(--main-width);
   308	
   309	    @media (min-width: 640px) {
   310	      --card-grid-columns: 2;
   311	    }
   312	
   313	    @media (min-width: 960px) {
   314	      --card-grid-columns: 3;
   315	    }
   316	
   317	    .cards__list {
   318	      display: flex;
   319	      flex-direction: row;
   320	      flex-wrap: wrap;
   321	      gap: var(--cards-gap);
   322	      justify-content: center;
   323	      padding: 1ch;
   324	    }
   325	
   326	    .card {
   327	      inline-size: calc((100% - var(--cards-gap) * (var(--card-grid-columns) - 1) ) / var(--card-grid-columns));
   328	    }
   329	
   330	    .card__header .card__column-name--current {
   331	      --btn-padding: 0.1em 0.5em;
   332	
   333	      background: none;
   334	      border: 1px solid currentColor;
   335	      color: var(--card-color);
   336	      display: inline-flex;
   337	      flex: 0 1 auto;
   338	      inline-size: fit-content;
   339	      margin: 0 0 0 auto;
   340	    }
   341	
   342	    .blank-slate--drag {
   343	      display: none;
   344	    }
   345	  }
   346	
   347	  /* Column Elements
   348	  /* ------------------------------------------------------------------------ */
   349	
   350	  .cards__header {
   351	    .cards.is-collapsed & {
   352	      block-size: 100%;
   353	    }
   354	
   355	    .cards.is-expanded & {
   356	      display: grid;
   357	      grid-template-areas: "menu expander maximize";
   358	      grid-template-columns: var(--column-width-collapsed) 1fr var(--column-width-collapsed);
   359	      padding-inline: var(--column-padding);
   360	    }
   361	  }
   362	
   363	  .cards__menu .btn--circle,
   364	  .cards__maximize-button {
   365	    --btn-background: transparent;
   366	
   367	    block-size: var(--column-width-collapsed);
   368	    inline-size: var(--column-width-collapsed);
   369	    opacity: 0;
   370	    outline-offset: -2px;
   371	
   372	    .cards:hover &,
   373	    &:focus-visible {
   374	      opacity: 1;
   375	    }
   376	
   377	    .cards.is-collapsed & {
   378	      display: none;
   379	    }
   380	  }
   381	
   382	  .cards__menu {
   383	    position: relative;
   384	    z-index: var(--z-popup);
   385	  }
   386	
   387	  .cards__maximize-button {
   388	    grid-area: maximize;
   389	  }
   390	
   391	  .cards__expander {
   392	    --gradient-direction: to bottom;
   393	
   394	    align-items: center;
   395	    border-radius: 99rem;
   396	    cursor: pointer;
   397	    display: flex;
   398	    flex-direction: row-reverse;
   399	    font-size: var(--text-x-small);
   400	    font-weight: 600;
   401	    gap: 0.5ch;
   402	    grid-area: expander;
   403	    justify-content: center;
   404	    outline: none;
   405	    outline-offset: -2px;
   406	    position: relative;
   407	    text-transform: uppercase;
   408	
   409	    &[disabled] {
   410	      opacity: 1;
   411	    }
   412	
   413	    @media (any-hover: hover) {
   414	      .is-collapsed:hover {
   415	        filter: brightness(0.9);
   416	      }
   417	    }
   418	
   419	    /* Progress */
   420	    &:after {
   421	      background: linear-gradient(var(--gradient-direction), var(--card-color), var(--column-color) 80%);
   422	      block-size: var(--column-width-collapsed);
   423	      border-radius: 99rem;
   424	      content: "";
   425	      inset: 0 0 auto;
   426	      margin-inline: auto;
   427	      max-block-size: var(--progress-max-height);
   428	      min-block-size: var(--column-width-collapsed);
   429	      opacity: 0;
   430	      position: absolute;
   431	      transition:
   432	        block-size 500ms var(--ease-out-overshoot),
   433	        inline-size var(--column-transition-duration) ease-out,
   434	        opacity var(--column-transition-duration) ease-out;
   435	      z-index: -1;
   436	    }
   437	
   438	    .no-transitions &:after {
